INSERT INTO `bowtie_preguntas` (`id`, `dimension_id`, `texto`, `evidencia`, `orden`, `creado_en`, `actualizado_en`, `activo`) VALUES
(260, 94, '¿Están definidos los contenidos para capacitación de Identificación de peligros y control de riesgos eléctricos.?', '1. Debe tener como mínimo lo indicado en instructivo de licencia corporativo basado en NFPA70E.\n2. Cada centro de trabajo puede definir contenidos adicionales a través de su comité eléctrico divisional.', 1, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(261, 94, '¿Está definido un programa de verificación de competencias para las tareas criticas según el cargo del trabajador?', '1. Que exista un programa de verificación de competencias de acuerdo con el nivel de riesgo del trabajador.', 2, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(262, 95, '¿Se da cumplimiento a la capacitación definida para otorgar licencia eléctrica?', '1. Registros de participación y aprobación de los requisitos indicados en instructivo corporativo.', 0, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(263, 95, '¿Se cuenta con personal competente en las diferentes áreas de trabajo y de acuerdo con los niveles de tensión?', '1. Revisar en terreno que el personal electricista porta la licencia vigente para el nivel de tensión.\n2. Que aplique RCQSV, reglas de oro y proceso de aislación y bloqueo según los reglamentos divisionales.\n3. Que utilice el EPP específico para el nivel de riesgo', 1, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(264, 95, '¿Se realiza verificación de competencias al personal calificado?', 'Proceso verificacion competencias:\n1. Aislación y bloque energías: \n- Identificación de energía, \n- Aislación energía\n- Bloqueo \n- Verificación energía cero (puesta a tierra si aplica) \n- Segregación del área a intervenir\n- Registro proceso bloqueo \n\n2. Selección y uso adecuado del instrumento de verificación de energía cero.\n3. Selección del EPP adecuado para la actividad', 2, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(265, 96, '¿Se ha establecido el proceso para solicitar ingreso a instalaciones eléctricas de acceso restringido?', '1. Requerir que en el acceso se encuentre instalado un letrero con el dueño del área y número de teléfono.\n2. Revisar que el documento indique la hora de ingreso y salida del recinto.', 0, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(266, 96, '¿Están definidos e identificados los recintos destinados a contener sistemas eléctricos energizados que requieren mantener control de acceso restringido?', '1. Revisar que se encuentre documentado los criterios para definir que un recinto que contiene sistemas eléctricos debe mantener ingreso controlado y restringido.', 1, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(267, 96, '¿Se ha establecido el tipo de letrero y su leyenda a utilizar en recintos de acceso controlado?', '1. Revisar que se indique Leyenda de acceso restringido.\n2. Revisar que se indique el nivel de tensión máximo en el interior del recinto.\n3. Revisar que se indique el nombre del responsable del recinto y medios de contacto (Frecuencia radial o número de teléfono).', 2, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(268, 96, '¿Está definido cuáles son las competencias técnicas del personal que está autorizado a ingresar en recintos que contiene sistemas eléctricos energizados?', '1. Revisar listado personal autorizado', 3, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(269, 97, '¿La segregación y acceso restringido se realiza de acuerdo con lo definido?', '1. Revisar en terreno que las áreas donde se realiza trabajos eléctricos se encuentren segregadas y señalizadas.\n2. Revisar que las salas eléctricas cuenten con mecanismos de acceso restringido.', 0, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(270, 97, '¿Existe un listado de salas eléctricas de la división?', '1. Registro con salas eléctricas con el área responsable.', 1, '2025-11-24 15:14:25', '2025-11-24 15:15:17', 0),
(271, 98, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(272, 98, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(273, 98, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(274, 99, '¿Se cumple con el proceso para otorgar permiso para el corte efectivo de energía y los factores de erosión del control?', '1. Solicitar el permiso de trabajo para asegurar que se haya completado en forma debida, cuente con las firmas correspondientes y se encuentre vigente: SODI o anexos de acuerdo al reglamento de bloqueo divisional.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(275, 99, '¿El personal que realiza el corte de energía es el que se encuentra autorizado?', '1. Verificar en terreno que el personal eléctrico porta su Licencia eléctrica interna y que cuya autorización esté acorde a los trabajos que realiza.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(276, 99, '¿La identificación y señalización de los puntos para el corte de energía se efectúa de acuerdo a lo definido?', '1. Se encuentre identificado el nivel de tensión presente.\n2. Estén identificados los puntos donde se debe realizar el corte de energía.\n3. Registro de planos unilineales vigentes.\n4. Existencia de planos unilineales actualizados.\n5. Revisar que la nomenclatura utilizada en los planos para la identificación de puntos para el corte de energía es la que se ha establecido.\n6. Revisar que la señalización definida es la que se está utilizando para la identificación de los puntos para el corte de energía.', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(277, 99, '¿Los instrumentos utilizados para medir tensión son los que están validados por el centro de trabajo?', '1. Verificar que los equipos utilizados se encuentran en el listado de equipos e instrumentos divionales, identificando aquellos que requieran calibración y/o cerificación', 3, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(278, 100, '¿Se han establecido auditorías/inspecciones al proceso de aislación y bloqueo?', '1. Revisar que se cuente con un programa de auditoría que indique nombre del responsable de ejecutarlas, fecha de ejecución y la frecuencia. \n2. Revisar que se cuente con informes de brechas detectadas y las acciones realizadas para el levantamiento de estas.\n3. Revisar que en caso de brechas no cerradas cuya fecha de cierre se haya cumplido, solicitar un plan de acción y responsables de su cumplimiento.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(279, 101, '¿La identificación de equipos e instalaciones eléctricas aisladas y bloqueadas se realiza de acuerdo con lo diseñado?', '1. Verificar mediante planos que la identificación se encuentra instalada en los puntos que se han definido.\n2. Revisar que la tarjeta utilizada sea la que se ha definido y contenga la información requerida.\n3. Revisar el libro en el que se registra la tarea de aislación y bloqueo.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(280, 102, '¿Están definidos las especificaciones técnicas de los equipos para medir ausencia de tensión e instalación de puesta a tierra?', '1. Revisar que existan las fichas técnicas de equipos a utilizar. \n2. Revisar que  las especificaciones de los equipos sean para el nivel de tensión que se necesita medir (Tester, detector de tensión, etc.).\n3. Revisar que los instrumentos de medición se encuentren en buen estado.\n4. Revisar que las puestas a tierra se encuentren en buenas condiciones y sean las adecuadas.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(281, 102, '¿Están documentados los requerimientos para puesta a tierra?', '1. Verificar que exista un documento, actualizado y validado por el centro de trabajo acorde a la tensión y corriente de falla. \n2. Verificar que exista un documento, actualizado y validado por el centro de trabajo que indique utilizar una línea de puesta a tierra acorde al tipo de sujeción donde esta debe ser instalada.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(282, 103, '¿El personal conoce el proceso de verificación de ausencia de tensión?', '1. Realizar preguntas al personal en terreno para evidenciar su conocimiento del proceso.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(283, 103, '¿Los puntos para conexión de líneas a tierra estén identificados?', '1. Verificar que los puntos para conexión de líneas a tierra estén identificados en terreno.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(284, 103, '¿Se realiza la verificación de estado de operatividad de la línea puesta a tierra?', '1. Solicitar check list de inspección de pre-uso.', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(285, 103, '¿Las líneas a tierra están instaladas en conformidad con lo indicado con el permiso de trabajo?', '1. Verificar que las líneas a tierra estén instaladas en conformidad con lo indicado con el permiso de trabajo.', 3, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(286, 103, '¿Las líneas de puesta a tierra se retiran una vez concluidos los trabajos?', '1. Revisar que las puestas a tierra se hayan retirado de los puntos donde fueron instaladas.', 4, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(287, 103, '¿El personal electricista utiliza los elementos de protección personal indicados?', '1. Revisar el uso y estado de EPP de acuerdo con lo definido para la actividad.', 5, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(288, 104, '¿Están definidos los requerimientos de diseño para tableros eléctricos?', '1. Verificar que existe un check list para revisión de tableros que contenga como mínimo: \n- Cumplimiento del diseño, protecciones eléctricas, que se encuentre cerrado, señalética de riesgo eléctrico y responsable del equipo.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(289, 104, '¿Se han definido los requerimientos para equipos eléctricos como generadores, máquinas autónomas y máquinas soldadoras?', '1. Verificar que los requerimientos para equipos eléctricos móviles estén documentado, actualizado y difundido.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(290, 104, '¿Se ha definido la necesidad de inspección a equipos, herramientas eléctricas y tableros eléctricos portátiles?', '1. Verificar que se encuentre designada el o las personas competentes responsables de la inspección de equipos y herramientas eléctricas.\n2. Revisar que esté definido el sistema de revisión y su frecuencia para equipos y herramientas eléctricas (Pruebas, check list, código de colores, etc.).\n3. Revisar que esté definido un sistema de chequeo para tableros eléctricos portátiles (Fuentes de energía y sus sistemas de protección).\n4. Que se indique el proceso cuando se detecten equipos o herramientas con fallas para dejar fuera de servicio (Retiro de terreno, uso de tarjeta de advertencia \"No Utilizar\").', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(291, 105, '¿Los tableros eléctricos cumplen con los requerimientos definidos?', '1. Verificar en terreno las especificaciones del tablero (marca de fabricación, tensión de servicio, corriente nominal, número de fases).\n2. Verificar en terreno que se encuentre identificado y en buenas condiciones el punto de bloqueo del tablero.\n3. Verificar en terreno el funcionamiento de instrumentos que tenga incorporado el tablero como amperímetros, voltímetros.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(292, 105, '¿Las herramientas eléctricas cumplen con lo establecido?', '1. Solicitar lista de verificación de herramientas eléctrica y verificar el buen estado de esta.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(293, 106, '¿Está documentado un proceso que establezca el conocimiento y competencias del personal electricista?', '1. Que exista un documento con contenido aprobado por la mesa eléctrica corporativa para autorizar la licencia eléctrica.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(294, 106, '¿Están definidos los contenidos para capacitación de Identificación de peligros y control de riesgos eléctricos.?', '1. Debe tener como mínimo lo indicado en instructivo de licencia corporativo basado en NFPA70E.\n2. Cada centro de trabajo puede definir contenidos adicionales a través de su comité eléctrico divisional.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(295, 106, '¿Está definido un programa de verificación de competencias para las tareas criticas según el cargo del trabajador?', '1. Que exista un programa de verificación de competencias de acuerdo con el nivel de riesgo del trabajador.', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(296, 107, '¿Se da cumplimiento a la capacitación definida para otorgar licencia eléctrica?', '1. Registros de participación y aprobación de los requisitos indicados en instructivo corporativo.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(297, 107, '¿Se cuenta con personal competente en las diferentes áreas de trabajo y de acuerdo con los niveles de tensión?', '1. Revisar en terreno que el personal electricista porta la licencia vigente para el nivel de tensión.\n2. Que aplique RCQSV, reglas de oro y proceso de aislación y bloqueo según los reglamentos divisionales.\n3. Que utilice el EPP específico para el nivel de riesgo', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(298, 107, '¿Se realiza verificación de competencias al personal calificado?', 'Proceso verificacion competencias:\n1. Aislación y bloque energías: \n- Identificación de energía, \n- Aislación energía\n- Bloqueo \n- Verificación energía cero (puesta a tierra si aplica) \n- Segregación del área a intervenir\n- Registro proceso bloqueo \n\n2. Selección y uso adecuado del instrumento de verificación de energía cero.\n3. Selección del EPP adecuado para la actividad', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(299, 108, '¿Se ha establecido el proceso para solicitar ingreso a instalaciones eléctricas de acceso restringido?', '1. Requerir que en el acceso se encuentre instalado un letrero con el dueño del área y número de teléfono.\n2. Revisar que el documento indique la hora de ingreso y salida del recinto.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(300, 108, '¿Están definidos e identificados los recintos destinados a contener sistemas eléctricos energizados que requieren mantener control de acceso restringido?', '1. Revisar que se encuentre documentado los criterios para definir que un recinto que contiene sistemas eléctricos debe mantener ingreso controlado y restringido.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(301, 108, '¿Se ha establecido el tipo de letrero y su leyenda a utilizar en recintos de acceso controlado?', '1. Revisar que se indique Leyenda de acceso restringido.\n2. Revisar que se indique el nivel de tensión máximo en el interior del recinto.\n3. Revisar que se indique el nombre del responsable del recinto y medios de contacto (Frecuencia radial o número de teléfono).', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(302, 108, '¿Está definido cuáles son las competencias técnicas del personal que está autorizado a ingresar en recintos que contiene sistemas eléctricos energizados?', '1. Revisar listado personal autorizado', 3, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(303, 109, '¿La segregación y acceso restringido se realiza de acuerdo con lo definido?', '1. Revisar en terreno que las áreas donde se realiza trabajos eléctricos se encuentren segregadas y señalizadas.\n2. Revisar que las salas eléctricas cuenten con mecanismos de acceso restringido.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(304, 109, '¿Existe un listado de salas eléctricas de la división?', '1. Registro con salas eléctricas con el área responsable.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(305, 110, '¿Están definidos los requerimientos para la elaboración de un programa de mantenimiento para los sistemas eléctricos?', '1. Verificar que el proceso este documentado, actualizado, difundido y evaluado.\n2. Verificar que esté designada la persona responsable de elaborar el plan de mantenimiento.\n3. Verificar que el plan de mantenimiento considere información el mantenimiento predictivo y preventivo teniendo en cuenta información técnica y manuales de operación de equipos e instalaciones eléctricas.\n4. Verificar la disposición de instructivos en caso de requerir mantenimiento a equipos e instalaciones nuevas y/o instalaciones eléctricas críticas para la continuidad operacional.', 0, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(306, 110, '¿Se han definido los criterios para reparaciones o reemplazo de partes o piezas de equipos e instalaciones eléctricas?', '1. El documento debe indicar disponer de tecnología que permita realizar un programa de mantenimiento predictivo detectando posibles fallas, daños o desgaste antes de que el equipo falle.\n2. El documento debe indicar disponer de un programa de mantenimiento preventivo que permita revisiones periódicas en forma permanente.\n3. El documento debe indicar disponer de personal competente para autorizar modificaciones, reparaciones y/o cambios de componentes de los sistemas eléctricos.', 1, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(307, 110, '¿Están definidos los equipos e instalaciones eléctricas críticas que requieren prioridad en el plan de mantenimiento?', '1. Evidenciar mediante un estudio técnico que indique los equipos e instalaciones que requieren mantenimiento y que indique su periodicidad.\n2. Verificar que se mantenga actualizado un listado de equipos críticos.', 2, '2025-11-24 15:15:17', '2025-11-24 15:15:52', 0),
(308, 111, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(309, 111, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(310, 111, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(311, 112, '¿Se cumple con el proceso para otorgar permiso para el corte efectivo de energía y los factores de erosión del control?', '1. Solicitar el permiso de trabajo para asegurar que se haya completado en forma debida, cuente con las firmas correspondientes y se encuentre vigente: SODI o anexos de acuerdo al reglamento de bloqueo divisional.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(312, 112, '¿El personal que realiza el corte de energía es el que se encuentra autorizado?', '1. Verificar en terreno que el personal eléctrico porta su Licencia eléctrica interna y que cuya autorización esté acorde a los trabajos que realiza.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(313, 112, '¿La identificación y señalización de los puntos para el corte de energía se efectúa de acuerdo a lo definido?', '1. Se encuentre identificado el nivel de tensión presente.\n2. Estén identificados los puntos donde se debe realizar el corte de energía.\n3. Registro de planos unilineales vigentes.\n4. Existencia de planos unilineales actualizados.\n5. Revisar que la nomenclatura utilizada en los planos para la identificación de puntos para el corte de energía es la que se ha establecido.\n6. Revisar que la señalización definida es la que se está utilizando para la identificación de los puntos para el corte de energía.', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(314, 112, '¿Los instrumentos utilizados para medir tensión son los que están validados por el centro de trabajo?', '1. Verificar que los equipos utilizados se encuentran en el listado de equipos e instrumentos divionales, identificando aquellos que requieran calibración y/o cerificación', 3, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(315, 113, '¿Se han establecido auditorías/inspecciones al proceso de aislación y bloqueo?', '1. Revisar que se cuente con un programa de auditoría que indique nombre del responsable de ejecutarlas, fecha de ejecución y la frecuencia. \n2. Revisar que se cuente con informes de brechas detectadas y las acciones realizadas para el levantamiento de estas.\n3. Revisar que en caso de brechas no cerradas cuya fecha de cierre se haya cumplido, solicitar un plan de acción y responsables de su cumplimiento.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(316, 114, '¿La identificación de equipos e instalaciones eléctricas aisladas y bloqueadas se realiza de acuerdo con lo diseñado?', '1. Verificar mediante planos que la identificación se encuentra instalada en los puntos que se han definido.\n2. Revisar que la tarjeta utilizada sea la que se ha definido y contenga la información requerida.\n3. Revisar el libro en el que se registra la tarea de aislación y bloqueo.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(317, 115, '¿Están definidos las especificaciones técnicas de los equipos para medir ausencia de tensión e instalación de puesta a tierra?', '1. Revisar que existan las fichas técnicas de equipos a utilizar. \n2. Revisar que  las especificaciones de los equipos sean para el nivel de tensión que se necesita medir (Tester, detector de tensión, etc.).\n3. Revisar que los instrumentos de medición se encuentren en buen estado.\n4. Revisar que las puestas a tierra se encuentren en buenas condiciones y sean las adecuadas.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(318, 115, '¿Están documentados los requerimientos para puesta a tierra?', '1. Verificar que exista un documento, actualizado y validado por el centro de trabajo acorde a la tensión y corriente de falla. \n2. Verificar que exista un documento, actualizado y validado por el centro de trabajo que indique utilizar una línea de puesta a tierra acorde al tipo de sujeción donde esta debe ser instalada.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(319, 116, '¿El personal conoce el proceso de verificación de ausencia de tensión?', '1. Realizar preguntas al personal en terreno para evidenciar su conocimiento del proceso.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(320, 116, '¿Los puntos para conexión de líneas a tierra estén identificados?', '1. Verificar que los puntos para conexión de líneas a tierra estén identificados en terreno.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(321, 116, '¿Se realiza la verificación de estado de operatividad de la línea puesta a tierra?', '1. Solicitar check list de inspección de pre-uso.', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(322, 116, '¿Las líneas a tierra están instaladas en conformidad con lo indicado con el permiso de trabajo?', '1. Verificar que las líneas a tierra estén instaladas en conformidad con lo indicado con el permiso de trabajo.', 3, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(323, 116, '¿Las líneas de puesta a tierra se retiran una vez concluidos los trabajos?', '1. Revisar que las puestas a tierra se hayan retirado de los puntos donde fueron instaladas.', 4, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(324, 116, '¿El personal electricista utiliza los elementos de protección personal indicados?', '1. Revisar el uso y estado de EPP de acuerdo con lo definido para la actividad.', 5, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(325, 117, '¿Están definidos los requerimientos de diseño para tableros eléctricos?', '1. Verificar que existe un check list para revisión de tableros que contenga como mínimo: \n- Cumplimiento del diseño, protecciones eléctricas, que se encuentre cerrado, señalética de riesgo eléctrico y responsable del equipo.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(326, 117, '¿Se han definido los requerimientos para equipos eléctricos como generadores, máquinas autónomas y máquinas soldadoras?', '1. Verificar que los requerimientos para equipos eléctricos móviles estén documentado, actualizado y difundido.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(327, 117, '¿Se ha definido la necesidad de inspección a equipos, herramientas eléctricas y tableros eléctricos portátiles?', '1. Verificar que se encuentre designada el o las personas competentes responsables de la inspección de equipos y herramientas eléctricas.\n2. Revisar que esté definido el sistema de revisión y su frecuencia para equipos y herramientas eléctricas (Pruebas, check list, código de colores, etc.).\n3. Revisar que esté definido un sistema de chequeo para tableros eléctricos portátiles (Fuentes de energía y sus sistemas de protección).\n4. Que se indique el proceso cuando se detecten equipos o herramientas con fallas para dejar fuera de servicio (Retiro de terreno, uso de tarjeta de advertencia \"No Utilizar\").', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(328, 118, '¿Los tableros eléctricos cumplen con los requerimientos definidos?', '1. Verificar en terreno las especificaciones del tablero (marca de fabricación, tensión de servicio, corriente nominal, número de fases).\n2. Verificar en terreno que se encuentre identificado y en buenas condiciones el punto de bloqueo del tablero.\n3. Verificar en terreno el funcionamiento de instrumentos que tenga incorporado el tablero como amperímetros, voltímetros.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(329, 118, '¿Las herramientas eléctricas cumplen con lo establecido?', '1. Solicitar lista de verificación de herramientas eléctrica y verificar el buen estado de esta.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(330, 119, '¿Está documentado un proceso que establezca el conocimiento y competencias del personal electricista?', '1. Que exista un documento con contenido aprobado por la mesa eléctrica corporativa para autorizar la licencia eléctrica.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(331, 119, '¿Están definidos los contenidos para capacitación de Identificación de peligros y control de riesgos eléctricos.?', '1. Debe tener como mínimo lo indicado en instructivo de licencia corporativo basado en NFPA70E.\n2. Cada centro de trabajo puede definir contenidos adicionales a través de su comité eléctrico divisional.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(332, 119, '¿Está definido un programa de verificación de competencias para las tareas criticas según el cargo del trabajador?', '1. Que exista un programa de verificación de competencias de acuerdo con el nivel de riesgo del trabajador.', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(333, 120, '¿Se da cumplimiento a la capacitación definida para otorgar licencia eléctrica?', '1. Registros de participación y aprobación de los requisitos indicados en instructivo corporativo.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(334, 120, '¿Se cuenta con personal competente en las diferentes áreas de trabajo y de acuerdo con los niveles de tensión?', '1. Revisar en terreno que el personal electricista porta la licencia vigente para el nivel de tensión.\n2. Que aplique RCQSV, reglas de oro y proceso de aislación y bloqueo según los reglamentos divisionales.\n3. Que utilice el EPP específico para el nivel de riesgo', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(335, 120, '¿Se realiza verificación de competencias al personal calificado?', 'Proceso verificacion competencias:\n1. Aislación y bloque energías: \n- Identificación de energía, \n- Aislación energía\n- Bloqueo \n- Verificación energía cero (puesta a tierra si aplica) \n- Segregación del área a intervenir\n- Registro proceso bloqueo \n\n2. Selección y uso adecuado del instrumento de verificación de energía cero.\n3. Selección del EPP adecuado para la actividad', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(336, 121, '¿Se ha establecido el proceso para solicitar ingreso a instalaciones eléctricas de acceso restringido?', '1. Requerir que en el acceso se encuentre instalado un letrero con el dueño del área y número de teléfono.\n2. Revisar que el documento indique la hora de ingreso y salida del recinto.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(337, 121, '¿Están definidos e identificados los recintos destinados a contener sistemas eléctricos energizados que requieren mantener control de acceso restringido?', '1. Revisar que se encuentre documentado los criterios para definir que un recinto que contiene sistemas eléctricos debe mantener ingreso controlado y restringido.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(338, 121, '¿Se ha establecido el tipo de letrero y su leyenda a utilizar en recintos de acceso controlado?', '1. Revisar que se indique Leyenda de acceso restringido.\n2. Revisar que se indique el nivel de tensión máximo en el interior del recinto.\n3. Revisar que se indique el nombre del responsable del recinto y medios de contacto (Frecuencia radial o número de teléfono).', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(339, 121, '¿Está definido cuáles son las competencias técnicas del personal que está autorizado a ingresar en recintos que contiene sistemas eléctricos energizados?', '1. Revisar listado personal autorizado', 3, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(340, 122, '¿La segregación y acceso restringido se realiza de acuerdo con lo definido?', '1. Revisar en terreno que las áreas donde se realiza trabajos eléctricos se encuentren segregadas y señalizadas.\n2. Revisar que las salas eléctricas cuenten con mecanismos de acceso restringido.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(341, 122, '¿Existe un listado de salas eléctricas de la división?', '1. Registro con salas eléctricas con el área responsable.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(342, 123, '¿Están definidos los requerimientos para la elaboración de un programa de mantenimiento para los sistemas eléctricos?', '1. Verificar que el proceso este documentado, actualizado, difundido y evaluado.\n2. Verificar que esté designada la persona responsable de elaborar el plan de mantenimiento.\n3. Verificar que el plan de mantenimiento considere información el mantenimiento predictivo y preventivo teniendo en cuenta información técnica y manuales de operación de equipos e instalaciones eléctricas.\n4. Verificar la disposición de instructivos en caso de requerir mantenimiento a equipos e instalaciones nuevas y/o instalaciones eléctricas críticas para la continuidad operacional.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(343, 123, '¿Se han definido los criterios para reparaciones o reemplazo de partes o piezas de equipos e instalaciones eléctricas?', '1. El documento debe indicar disponer de tecnología que permita realizar un programa de mantenimiento predictivo detectando posibles fallas, daños o desgaste antes de que el equipo falle.\n2. El documento debe indicar disponer de un programa de mantenimiento preventivo que permita revisiones periódicas en forma permanente.\n3. El documento debe indicar disponer de personal competente para autorizar modificaciones, reparaciones y/o cambios de componentes de los sistemas eléctricos.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(344, 123, '¿Están definidos los equipos e instalaciones eléctricas críticas que requieren prioridad en el plan de mantenimiento?', '1. Evidenciar mediante un estudio técnico que indique los equipos e instalaciones que requieren mantenimiento y que indique su periodicidad.\n2. Verificar que se mantenga actualizado un listado de equipos críticos.', 2, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(345, 124, '¿Se da cumplimiento al programa de mantenimiento de acuerdo con lo establecido?', '1. Verificar la ejecución de mantenimiento a través de registros y el plan de mantenimiento.\n2. Verificar en terreno el cumplimiento del plan de mantenimiento.', 0, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(346, 124, '¿El personal eléctrico ha sido capacitado y con evaluación aprobada y vigente  en los procesos de mantención para equipos e instalaciones eléctricas y conoce los factores de erosión?', '1. Revisar que se han abordado todos los ítems de la capacitación para el logro de las competencias del personal electricista.', 1, '2025-11-24 15:15:52', '2025-11-24 15:17:00', 0),
(347, 126, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(348, 126, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(349, 126, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(350, 127, '¿Se cumple con el proceso para otorgar permiso para el corte efectivo de energía y los factores de erosión del control?', '1. Solicitar el permiso de trabajo para asegurar que se haya completado en forma debida, cuente con las firmas correspondientes y se encuentre vigente: SODI o anexos de acuerdo al reglamento de bloqueo divisional.', 0, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(351, 127, '¿El personal que realiza el corte de energía es el que se encuentra autorizado?', '1. Verificar en terreno que el personal eléctrico porta su Licencia eléctrica interna y que cuya autorización esté acorde a los trabajos que realiza.', 1, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(352, 127, '¿La identificación y señalización de los puntos para el corte de energía se efectúa de acuerdo a lo definido?', '1. Se encuentre identificado el nivel de tensión presente.\n2. Estén identificados los puntos donde se debe realizar el corte de energía.\n3. Registro de planos unilineales vigentes.\n4. Existencia de planos unilineales actualizados.\n5. Revisar que la nomenclatura utilizada en los planos para la identificación de puntos para el corte de energía es la que se ha establecido.\n6. Revisar que la señalización definida es la que se está utilizando para la identificación de los puntos para el corte de energía.', 2, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(353, 127, '¿Los instrumentos utilizados para medir tensión son los que están validados por el centro de trabajo?', '1. Verificar que los equipos utilizados se encuentran en el listado de equipos e instrumentos divionales, identificando aquellos que requieran calibración y/o cerificación', 3, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(354, 128, '¿Se han establecido auditorías/inspecciones al proceso de aislación y bloqueo?', '1. Revisar que se cuente con un programa de auditoría que indique nombre del responsable de ejecutarlas, fecha de ejecución y la frecuencia. \n2. Revisar que se cuente con informes de brechas detectadas y las acciones realizadas para el levantamiento de estas.\n3. Revisar que en caso de brechas no cerradas cuya fecha de cierre se haya cumplido, solicitar un plan de acción y responsables de su cumplimiento.', 0, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(355, 129, '¿La identificación de equipos e instalaciones eléctricas aisladas y bloqueadas se realiza de acuerdo con lo diseñado?', '1. Verificar mediante planos que la identificación se encuentra instalada en los puntos que se han definido.\n2. Revisar que la tarjeta utilizada sea la que se ha definido y contenga la información requerida.\n3. Revisar el libro en el que se registra la tarea de aislación y bloqueo.', 0, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(356, 130, '¿Están definidos las especificaciones técnicas de los equipos para medir ausencia de tensión e instalación de puesta a tierra?', '1. Revisar que existan las fichas técnicas de equipos a utilizar. \n2. Revisar que  las especificaciones de los equipos sean para el nivel de tensión que se necesita medir (Tester, detector de tensión, etc.).\n3. Revisar que los instrumentos de medición se encuentren en buen estado.\n4. Revisar que las puestas a tierra se encuentren en buenas condiciones y sean las adecuadas.', 0, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(357, 130, '¿Están documentados los requerimientos para puesta a tierra?', '1. Verificar que exista un documento, actualizado y validado por el centro de trabajo acorde a la tensión y corriente de falla. \n2. Verificar que exista un documento, actualizado y validado por el centro de trabajo que indique utilizar una línea de puesta a tierra acorde al tipo de sujeción donde esta debe ser instalada.', 1, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(358, 131, '¿El personal conoce el proceso de verificación de ausencia de tensión?', '1. Realizar preguntas al personal en terreno para evidenciar su conocimiento del proceso.', 0, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(359, 131, '¿Los puntos para conexión de líneas a tierra estén identificados?', '1. Verificar que los puntos para conexión de líneas a tierra estén identificados en terreno.', 1, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(360, 131, '¿Se realiza la verificación de estado de operatividad de la línea puesta a tierra?', '1. Solicitar check list de inspección de pre-uso.', 2, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(361, 131, '¿Las líneas a tierra están instaladas en conformidad con lo indicado con el permiso de trabajo?', '1. Verificar que las líneas a tierra estén instaladas en conformidad con lo indicado con el permiso de trabajo.', 3, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(362, 131, '¿Las líneas de puesta a tierra se retiran una vez concluidos los trabajos?', '1. Revisar que las puestas a tierra se hayan retirado de los puntos donde fueron instaladas.', 4, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(363, 131, '¿El personal electricista utiliza los elementos de protección personal indicados?', '1. Revisar el uso y estado de EPP de acuerdo con lo definido para la actividad.', 5, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(364, 132, '¿Están definidos los requerimientos de diseño para tableros eléctricos?', '1. Verificar que existe un check list para revisión de tableros que contenga como mínimo: \n- Cumplimiento del diseño, protecciones eléctricas, que se encuentre cerrado, señalética de riesgo eléctrico y responsable del equipo.', 0, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
(365, 132, '¿Se han definido los requerimientos para equipos eléctricos como generadores, máquinas autónomas y máquinas soldadoras?', '1. Verificar que los requerimientos para equipos eléctricos móviles estén documentado, actualizado y difundido.', 1, '2025-11-24 15:17:00', '2025-11-24 15:18:47', 0),
