INSERT INTO `bowtie_preguntas` (`id`, `dimension_id`, `texto`, `evidencia`, `orden`, `creado_en`, `actualizado_en`, `activo`) VALUES
(778, 303, '¿El trabajador cuenta con la autorización para ingresar a los cuerpos líquidos contenidos?', 'Se debe verificar la autorización (registro) para ingresar al cuerpo líquido contenido.', 1, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(779, 304, '¿Los trabajadores están capacitados en el protocolo de control de acceso al cuerpo líquido contenido?', 'Solicitar las siguientes evidencias:\n1. Registro de capacitación y evaluación', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(780, 305, '¿ Se cuenta con un proceso documentado que indique las capacitaciones mínimas requeridas y la autorización?', '\"Todo trabajador que realice tarea interactuando con este riesgo crítico, deberá tener una credencial (u otro medio) que indique las siguientes competencias:\n\nPara los trabajadores que realicen tareas  que se realicen en el perímetro del cuerpo liquido se solicitará lo siguiente:\n-Primeros auxilios y RCP\n-Procedimiento de emergencia del área\n\nPara los trabajadores que realicen tareas dentro del cuerpo líquido contenido se solicitará lo siguiente:\n -Primeros auxilios y RCP\n-Procedimiento de emergencia del área\n-Uso de SPDC (en caso que aplique)  en piscinas / uso de chaleco salvavidas en embalses y tranques\n-Saber nadar (puede ser a través de un curso o una declaración notarial, u otro registro definido por la organización)\n\"', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(781, 306, '¿ El personal que trabaja en el perímetro o dentro del cuerpo líquido contenido esta con su autorización vigente?', 'Se debe solicitar Credencial de Autorización u otro medio que se haya definido (QR, listado, etc.).', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(782, 307, '¿ Existe un procedimiento, estándar y/o documento que establezca la comunicación bidireccional obligatorio?', '\"El documento debe contener como mínimo lo siguiente:\n- Responsables\n- Equipos a utilizar \n- Frecuencias \n- Definición de pruebas de comunicación\n- Disposición \n- Autonomía \"', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(783, 308, '\"\n¿Se realizaron las pruebas de comunicación antes de iniciar el trabajo?\"', 'Entrevistar a trabajadores consultando si realizaron las pruebas al inicio del trabajo, y consultar cuál es la frecuencia o número de emergencia', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(784, 309, '¿ Las estructuras fijas que componen el cuerpo líquido contenido se encuentran diseñadas y definidas de acuerdo a lo establecido en el RC22?', '\"Diseño de las estructuras definida de acuerdo a lo establecido en el Riesgo Crítico 22 (Barandas, Cargas Máximas, Parrillas, etc.)\n\nTodo cuerpo de líquido contenido debe tener al menos una estructura para salida de emergencia desde el interior del cuerpo líquido (por ejemplo escalera, rampa, etc.). Este punto para embalses y tranques debe realizarse una evaluación técnica para definir si aplica.\"', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(785, 309, '¿Las estructuras flotantes como balsas, muelles flotantes, pasarelas u otras estructuras cumplen con los siguientes requisitos?', '\"Se requieren los siguientes requisitos:\n-Memoria de cálculo\n-Capacidad máxima de carga \n-Diseño de anclaje\n-Las estructuras para tránsito de persona deben tener baranda con continuidad (no existan espacios entre una baranda y otra en la que pueda caer una persona) y su altura debe cumplir con la memoria de cálculo\"', 1, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(786, 309, 'Los cuerpos líquidos contenidos deben contar las siguientes señaléticas', '\"Las siguientes señaléticas deben ser visibles día y noche:\n1.-Riesgo de Inmersión más el ícono del riesgo crítico\n2.-Sólo ingreso personal autorizado\n3.-Ubicación del Kit de maniobras de emergencia (flotador - cuerda de vida - chaleco salvavidas)\n4.- Control de acceso y números de emergencia\"', 2, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(787, 310, '¿ Se encuentra operativa la infraestructura y señalética definida para el cuerpo líquido contenido?', '\"Verificar en terreno las siguientes condiciones:\n-Plan de inspección vigente \n-Plan de mantenimiento vigente\n \"', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(788, 310, '¿ El personal que realiza actividades rutinarias (operación/mantenimiento) se encuentra capacitado en el RC 22?', 'Se debe evidenciar la capacitación de los trabajadores respecto al Riesgo Crítico 22', 1, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(789, 311, '¿Se dispone de un plan de emergencia específico para la caída a un cuerpo líquido contenido?', '\"Se encuentra actualizado y aprobado el plan de emergencia específico que a lo menos indique:\n-Elementos de rescate\n-Flujograma de actuación ante la emergencia\n-Responsables\"', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(790, 311, '¿Están definidos en un documento los equipamientos de rescate en caso de caída?', '\"El documento debe indicar a lo menos los siguientes elementos:\n-Flotadores con cuerda (la longitud de la cuerda debe ser de acuerdo a evaluación)\n-Línea de vida (SPDC) en caso que aplique\n-Chaleco salvavidas\n-Bote inflable (aplica para tranques y relaves)\n\"', 1, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(791, 312, '¿Los elementos de rescate se encuentras operativos y en buenas condiciones?', 'Revisar el estado y funcionalidad de los elementos de rescate', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(792, 312, '¿Se ha realizado simulacros utilizando los elementos de rescate (chaleco salvavidas, flotadores, etc.).?', 'Registro de simulacro', 1, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(793, 312, '¿El personal se encuentra capacitado y evaluado en el plan de emergencia?', 'Registro de capacitación y evaluación', 2, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(794, 312, '¿El personal asignado para maniobras de rescate ha sido entrenado en el uso de los elementos de rescate?', 'Registro de capacitación y evaluación', 3, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(795, 313, '¿Existe un documento por parte de la Brigada de emergencia que indiqué qué hacer en caso de una inmersión?', 'Documento que indique la respuesta ante una emergencia de inmersión.', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(796, 314, '¿La brigada de emergencia ha participado en los simulacros de emergencia de inmersión?', 'Registro del simulacro', 0, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(797, 314, '¿Los brigadistas se encuentran capacitados en la respuesta ante emergencia de inmersión?', 'Registro de capacitación y evaluación', 1, '2025-11-25 09:28:02', '2025-11-25 09:28:32', 0),
(798, 315, '¿El recinto cuenta con cierre perimetral de acuerdo a lo diseñado y/o definido? (Esta pregunta no aplica para tranques de relave y embalses)', 'Se debe solicitar la siguiente información:\n1- Layout del recinto \n2. Características del cierre perimetral (Altura mínima 1,20) \n3.-Para las características de diseño del cierre perimetral debe existir un documento que indique las especificaciones (por ejemplo un procedimiento que indique la materialidad del cierre, etc.', 0, '2025-11-25 09:28:32', '2025-11-25 09:28:48', 0),
(799, 315, '¿ El control de acceso se encuentra documentado, estandarizado y/o procedimentado?', '\"El documento debe poseer las siguientes características:     \n1. Layout general del recinto (incluyendo plan de tránsito)\n2. Responsables de autorizar el ingreso\n3. Las vías de evacuación \n4. Forma de registro ingreso/salida (QR, libro, etc.)\n5. La persona que esté controlando el acceso debe garantizar que el trabajador que ingrese cuente con:\na.- un medio de comunicación en caso de emergencia\nb.- los EPP definidos en el procedimiento de la tarea\nPara los trabajos en solitario se debe evaluar el Instructivo corporativo de trabajo en solitario SIGO-I-053\"', 1, '2025-11-25 09:28:32', '2025-11-25 09:28:48', 0),
(800, 316, '¿El cuerpo líquido contenido cuenta con su cierre perimetral completo? (Esta pregunta no aplica para tranques de relave y embalses)', 'Verificar que no existan espacios / aberturas que pudiesen generar un ingreso no autorizado.\nVerificar que el cierre se encuentre en buenas condiciones (corrosión, deformaciones, con todos sus elementos, etc.)', 0, '2025-11-25 09:28:32', '2025-11-25 09:28:48', 0),
(801, 316, '¿El trabajador cuenta con la autorización para ingresar a los cuerpos líquidos contenidos?', 'Se debe verificar la autorización (registro) para ingresar al cuerpo líquido contenido.', 1, '2025-11-25 09:28:32', '2025-11-25 09:28:48', 0),
(802, 317, '¿Los trabajadores están capacitados en el protocolo de control de acceso al cuerpo líquido contenido?', 'Solicitar las siguientes evidencias:\n1. Registro de capacitación y evaluación', 0, '2025-11-25 09:28:32', '2025-11-25 09:28:48', 0),
