(695, 76, 'ED-CCP3-IEE', '', '', '2. Revisar que  las especificaciones de los equipos sean para el nivel de tensión que se necesita medir (Tester, detector de tensión, etc.).', '', NULL, '', '', '', NULL, '', 0.00, '', '', 19, 0, '2025-11-27 12:33:45', '2025-11-27 13:21:06', 343, NULL, '', '', NULL, 0.00, NULL, NULL, NULL),
(696, 76, 'ED-CCP3-IEE', '', '', '3. Revisar que los instrumentos de medición se encuentren en buen estado.', '', NULL, '', '', '', NULL, '', 0.00, '', '', 20, 0, '2025-11-27 12:33:45', '2025-11-27 13:21:06', 343, NULL, '', '', NULL, 0.00, NULL, NULL, NULL),
(697, 76, 'ED-CCP3-IEE', '', '', '4. Revisar que las puestas a tierra se encuentren en buenas condiciones y sean las adecuadas.', '', NULL, '', '', '', NULL, '', 0.00, '', '', 21, 0, '2025-11-27 12:33:45', '2025-11-27 13:21:06', 343, NULL, '', '', NULL, 0.00, NULL, NULL, NULL),
(698, 76, 'ED-CCP3-IEE', '', '¿Están documentados los requerimientos para puesta a tierra?', '1. Verificar que exista un documento, actualizado y validado por el centro de trabajo acorde a la tensión y corriente de falla.', '', NULL, '', '', '', NULL, '', 0.00, '', '', 22, 0, '2025-11-27 12:33:45', '2025-11-27 13:21:06', 343, NULL, '', '', NULL, 0.00, NULL, NULL, NULL);
