(1709, 76, 'ED-CCP6-IEE', '', '¿Está definido cuáles son las competencias técnicas del personal que está autorizado a ingresar en recintos que contiene sistemas eléctricos energizados?', '1. Revisar listado personal autorizado', '', NULL, '', '', '', NULL, '', NULL, '', '', 65, 0, '2025-12-01 14:29:24', '2025-12-01 14:29:29', 346, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1710, 76, 'ED-CCP6-IEE', '', '', '2. Revisar que las salas eléctricas cuenten con mecanismos de acceso restringido.', '', NULL, '', '', '', NULL, '', NULL, '', '', 67, 0, '2025-12-01 14:29:24', '2025-12-01 14:29:29', 346, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1711, 76, 'ED-CCP6-IEE', '', '¿Existe un listado de salas eléctricas de la división?', '1. Registro con salas eléctricas con el área responsable.', '', NULL, '', '', '', NULL, '', NULL, '', '', 68, 0, '2025-12-01 14:29:24', '2025-12-01 14:29:29', 346, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
