(1812, 76, 'ED-CCP3-IEE', '', '', '2. Revisar que  las especificaciones de los equipos sean para el nivel de tensión que se necesita medir (Tester, detector de tensión, etc.).', '', NULL, '', '', '', NULL, '', NULL, '', '', 19, 0, '2025-12-01 14:29:30', '2025-12-01 14:29:48', 343, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1813, 76, 'ED-CCP3-IEE', '', '', '3. Revisar que los instrumentos de medición se encuentren en buen estado.', '', NULL, '', '', '', NULL, '', NULL, '', '', 20, 0, '2025-12-01 14:29:30', '2025-12-01 14:29:48', 343, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1814, 76, 'ED-CCP3-IEE', '', '', '4. Revisar que las puestas a tierra se encuentren en buenas condiciones y sean las adecuadas.', '', NULL, '', '', '', NULL, '', NULL, '', '', 21, 0, '2025-12-01 14:29:30', '2025-12-01 14:29:48', 343, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1815, 76, 'ED-CCP3-IEE', '', '¿Están documentados los requerimientos para puesta a tierra?', '1. Verificar que exista un documento, actualizado y validado por el centro de trabajo acorde a la tensión y corriente de falla.', '', NULL, '', '', '', NULL, '', NULL, '', '', 22, 0, '2025-12-01 14:29:30', '2025-12-01 14:29:48', 343, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1816, 76, 'ED-CCP3-IEE', '', '', '2. Verificar que exista un documento, actualizado y validado por el centro de trabajo que indique utilizar una línea de puesta a tierra acorde al tipo de sujeción donde esta debe ser instalada.', '', NULL, '', '', '', NULL, '', NULL, '', '', 23, 0, '2025-12-01 14:29:30', '2025-12-01 14:29:48', 343, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1817, 76, 'ED-CCP3-IEE', '', '¿Los puntos para conexión de líneas a tierra estén identificados?', '1. Verificar que los puntos para conexión de líneas a tierra estén identificados en terreno.', '', NULL, '', '', '', NULL, '', NULL, '', '', 25, 0, '2025-12-01 14:29:30', '2025-12-01 14:29:48', 343, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
