(3474, 87, 'ED-CCP5-IEE', '', '¿Se cuenta con personal competente en las diferentes áreas de trabajo y de acuerdo con los niveles de tensión?', '1. Revisar en terreno que el personal electricista porta la licencia vigente para el nivel de tensión.', '', NULL, '', '', '', NULL, '', 0.00, '', '', 46, 0, '2025-11-27 15:12:29', '2025-11-27 15:20:44', 345, NULL, '', '', NULL, 0.00, NULL, NULL, NULL),
(3475, 87, 'ED-CCP5-IEE', '', '', '2. Que aplique RCQSV, reglas de oro y proceso de aislación y bloqueo según los reglamentos divisionales.', '', NULL, '', '', '', NULL, '', 0.00, '', '', 47, 0, '2025-11-27 15:12:29', '2025-11-27 15:20:44', 345, NULL, '', '', NULL, 0.00, NULL, NULL, NULL),
(3476, 87, 'ED-CCP5-IEE', '', '', '3. Que utilice el EPP específico para el nivel de riesgo', '', NULL, '', '', '', NULL, '', 0.00, '', '', 48, 0, '2025-11-27 15:12:29', '2025-11-27 15:20:44', 345, NULL, '', '', NULL, 0.00, NULL, NULL, NULL),
